{"cti_reasoning":"The state i=3, sq=50, odd=31 satisfies P because the guard odd==5'd1 is false, but it violates R since sq != i*i (50 != 9) and odd != {i,1'b1} (31 != 7). With step low the design idles there forever; one step makes odd <= 31+2 = 5'd1 (wraps in 5 bits) while sq <= 50+31 = 81, so the next state has the guard true with sq nonzero, breaking P.","cti_state":[{"signal":"i","value":"4'd3"},{"signal":"sq","value":"8'd50"},{"signal":"odd","value":"5'd31"}],"invariants":["sq == ({4'd0, i} * {4'd0, i})","odd == {i, 1'b1}"],"verilog":"module sq_odd_walker (
    input wire clk,
    input wire rst,
    input wire step,
    output reg [3:0] i,
    output reg [7:0] sq,
    output reg [4:0] odd
);
    initial begin
        i   = 4'd0;
        sq  = 8'd0;
        odd = 5'd1;
    end

    // sum-of-odd-numbers identity: (n+1)^2 = n^2 + (2n+1)
    wire go = step && (i != 4'd15);

    always @(posedge clk) begin
        if (rst) begin
            i   <= 4'd0;
            sq  <= 8'd0;
            odd <= 5'd1;
        end else if (go) begin
            i   <= i + 4'd1;
            sq  <= sq + odd;
            odd <= odd + 5'd2;
        end
    end

    // P: the running square is zero whenever the odd stride is back at one
    always @(posedge clk)
        if (odd == 5'd1)
            assert (sq == 8'd0);
endmodule","top_module":"sq_odd_walker","clock":"clk","antecedents":["odd == 5'd1"],"sanity_covers":["i == 4'd3 && sq == 8'd9","odd == 5'd7"]}

{"cti_reasoning": "The state has count==2 so the guard of P (count==1) is false and P holds vacuously, but it violates R because the shadow register max_shadow (8'd5) does not equal the tail element e1 (8'd2). With i_ce low the design sits in this state forever; one remove step then shifts e1 into e0 (e0'=8'd2), decrements count to 1, and leaves max_shadow at 8'd5, so the next state has count==1 with max_shadow != e0 and P fails.", "cti_state": [{"signal": "count", "value": "2'd2"}, {"signal": "e0", "value": "8'd1"}, {"signal": "e1", "value": "8'd2"}, {"signal": "max_shadow", "value": "8'd5"}], "invariants": ["count <= 2'd2", "(count != 2'd2) || (max_shadow == e1)"], "verilog": "module sorted_pair (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire ins,
    input wire rem,
    input wire [7:0] val,
    output reg [1:0] count
);
    reg [7:0] e0, e1, max_shadow;
    initial begin count = 2'd0; e0 = 8'd0; e1 = 8'd0; max_shadow = 8'd0; end

    wire do_ins = i_ce && ins && !rem && (count != 2'd2);
    wire do_rem = i_ce && rem && !ins && (count != 2'd0);

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0; e0 <= 8'd0; e1 <= 8'd0; max_shadow <= 8'd0;
        end else if (do_ins) begin
            count <= count + 2'd1;
            if (count == 2'd0) begin
                e0 <= val;  max_shadow <= val;
            end else if (val >= e0) begin
                e1 <= val;  max_shadow <= val;
            end else begin
                e0 <= val;  e1 <= e0;  max_shadow <= e0;
            end
        end else if (do_rem) begin
            count <= count - 2'd1;
            if (count == 2'd2) e0 <= e1;
        end
    end

    always @(posedge clk)
        if (count == 2'd1)
            assert (max_shadow == e0);
endmodule", "top_module": "sorted_pair", "clock": "clk", "antecedents": ["count == 2'd1"], "sanity_covers": ["count == 2'd2", "count == 2'd1"]}

{"cti_reasoning":"State S has done=0 so the guarded property (done implies !calc) holds vacuously, but it has both idle and calc high, violating the one-hot control invariant; with ce low the design sits in S forever, and one step with ce=1, start=1 and b==0 (so finish=1) drives calc<=(idle&&start)=1 and done<=(calc&&finish)=1, making done && calc true and breaking the property.","cti_state":[{"signal":"idle","value":"1'b1"},{"signal":"calc","value":"1'b1"},{"signal":"done","value":"1'b0"},{"signal":"a","value":"4'd6"},{"signal":"b","value":"4'd0"}],"invariants":["(idle & ~calc & ~done) | (~idle & calc & ~done) | (~idle & ~calc & done)","idle | calc | done"],"verilog":"module gcd_ctrl (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       ack,
    input  wire [3:0] x,
    input  wire [3:0] y,
    output reg  [3:0] a,
    output reg  [3:0] b,
    output reg        idle,
    output reg        calc,
    output reg        done
);
    initial begin a = 4'd0; b = 4'd0; idle = 1'b1; calc = 1'b0; done = 1'b0; end

    wire finish = (b == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            idle <= (idle && !start) || (done && ack);
            calc <= (idle && start)  || (calc && !finish);
            done <= (calc && finish) || (done && !ack);

            if (idle && start) begin
                a <= x;
                b <= y;
            end else if (calc && !finish) begin
                if (a >= b) begin
                    a <= a - b;
                end else begin
                    a <= b;
                    b <= a;
                end
            end
        end
    end

    always @(posedge clk)
        if (done)
            assert (!calc);
endmodule","top_module":"gcd_ctrl","clock":"clk","antecedents":["done"],"sanity_covers":["done == 1'b1","calc == 1'b1"]}

{"cti_reasoning":"The state nmatch=7, nchars=0 satisfies P vacuously (nmatch is not 8, so nothing is required of nchars), but it violates R because nmatch > nchars. With ce low the scanner sits in this state forever; one step with ce=1 and ch_match=1 (scanning is not done since nchars<8) yields nmatch=8 while nchars=1, so the guard fires with nchars != 8 and P fails.","cti_state":[{"signal":"nchars","value":"4'd0"},{"signal":"nmatch","value":"4'd7"}],"invariants":["nmatch <= nchars","nchars <= 4'd8","nmatch <= 4'd8"],"verilog":"module char_occurrence_scan (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire ch_match,
    output reg [3:0] nchars,
    output reg [3:0] nmatch,
    output wire done
);
    initial nchars = 4'd0;
    initial nmatch = 4'd0;

    // scan a fixed 8-character string, counting occurrences of the target char
    assign done = (nchars == 4'd8);

    always @(posedge clk) begin
        if (rst) begin
            nchars <= 4'd0;
            nmatch <= 4'd0;
        end else if (ce && !done) begin
            nchars <= nchars + 4'd1;
            if (ch_match)
                nmatch <= nmatch + 4'd1;
        end
    end

    // P: if every character matched, the whole string must have been consumed
    always @(posedge clk)
        if (nmatch == 4'd8)
            assert (nchars == 4'd8);
endmodule","top_module":"char_occurrence_scan","clock":"clk","antecedents":["nmatch == 4'd8"],"sanity_covers":["nmatch == 4'd8","nchars == 4'd8","nmatch == 4'd3"]}

{"cti_reasoning":"State S has count=1 with wptr==rptr, which satisfies P vacuously (P only constrains count==0) but violates R because the occupancy no longer matches the pointer difference ((wptr-rptr)&3 == 0 != 1). With push=pop=0 the design idles in S indefinitely; then a single pop (count!=0 so it is accepted) decrements count to 0 and advances rptr to 1, giving count==0 with wptr=0 != rptr=1, breaking P.","cti_state":[{"signal":"count","value":"3'd1"},{"signal":"wptr","value":"2'd0"},{"signal":"rptr","value":"2'd0"}],"invariants":["count <= 3'd4","count[1:0] == (wptr - rptr)"],"verilog":"module ringq (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output wire full,
    output wire empty
);
    reg [1:0] wptr = 2'd0;
    reg [1:0] rptr = 2'd0;
    reg [2:0] count = 3'd0;
    reg [7:0] mem [0:3];

    assign full  = (count == 3'd4);
    assign empty = (count == 3'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                mem[wptr] <= din;
                wptr <= wptr + 2'd1;
            end
            if (do_pop)
                rptr <= rptr + 2'd1;
            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    assign dout = mem[rptr];

    always @(posedge clk)
        if (count == 3'd0) assert (wptr == rptr);
endmodule","top_module":"ringq","clock":"clk","antecedents":["count == 3'd0"],"sanity_covers":["count == 3'd2","count == 3'd0 && wptr == 2'd1"]}

{"cti_reasoning":"In state S the stack pointer is 1 so the guard (sp==0) is false and P holds vacuously, but the accumulator does not equal the XOR of the live entries (xor_acc=4'd5 while m0=4'd3), so R is false. With push and pop both low the design sits in S forever; a single pop then drives sp to 0 while xor_acc becomes 5^3 = 4'd6, so the next state has sp==0 with a nonzero accumulator and P fails.","cti_state":[{"signal":"sp","value":"3'd1"},{"signal":"xor_acc","value":"4'd5"},{"signal":"m0","value":"4'd3"},{"signal":"m1","value":"4'd0"},{"signal":"m2","value":"4'd0"},{"signal":"m3","value":"4'd0"}],"invariants":["sp <= 3'd4","xor_acc == ((sp > 3'd0 ? m0 : 4'd0) ^ (sp > 3'd1 ? m1 : 4'd0) ^ (sp > 3'd2 ? m2 : 4'd0) ^ (sp > 3'd3 ? m3 : 4'd0))"],"verilog":"module stack_xor (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [3:0] data,
    output reg [2:0] sp,
    output reg [3:0] xor_acc
);
    reg [3:0] m0, m1, m2, m3;
    initial begin sp = 0; xor_acc = 0; m0 = 0; m1 = 0; m2 = 0; m3 = 0; end

    wire do_push = push && !pop && (sp != 3'd4);
    wire do_pop  = pop  && !push && (sp != 3'd0);
    wire [3:0] top = (sp == 3'd1) ? m0 : (sp == 3'd2) ? m1 : (sp == 3'd3) ? m2 : m3;

    always @(posedge clk) begin
        if (rst) begin
            sp <= 3'd0;
            xor_acc <= 4'd0;
        end else if (do_push) begin
            case (sp)
                3'd0:    m0 <= data;
                3'd1:    m1 <= data;
                3'd2:    m2 <= data;
                default: m3 <= data;
            endcase
            sp <= sp + 3'd1;
            xor_acc <= xor_acc ^ data;
        end else if (do_pop) begin
            sp <= sp - 3'd1;
            xor_acc <= xor_acc ^ top;
        end
    end

    always @(posedge clk)
        if (sp == 3'd0)
            assert (xor_acc == 4'd0);
endmodule","top_module":"stack_xor","clock":"clk","antecedents":["sp == 3'd0"],"sanity_covers":["sp == 3'd3"]}

{"cti_reasoning":"S has empty_r=0 and full_r=0, so the property (empty implies not full) holds, but it violates R because count=3'd2 while wptr-rptr=0 (pointers equal with a non-multiple-of-4 occupancy). With i_ce low the design sits in S forever; then one simultaneous push+pop is enabled (neither flag blocks it), both pointers advance so nw==nr still holds, which sets empty_r<=1 AND full_r<=1 in the same cycle, breaking the property in the next state.","cti_state":[{"signal":"wptr","value":"2'd0"},{"signal":"rptr","value":"2'd0"},{"signal":"count","value":"3'd2"},{"signal":"empty_r","value":"1'b0"},{"signal":"full_r","value":"1'b0"}],"invariants":["count <= 3'd4","empty_r == (count == 3'd0)","full_r == (count == 3'd4)","count[1:0] == wptr - rptr"],"verilog":"module ringq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire push,
    input wire pop
);
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg       empty_r, full_r;
    initial begin wptr = 2'd0; rptr = 2'd0; count = 3'd0; empty_r = 1'b1; full_r = 1'b0; end

    wire do_push = i_ce && push && !full_r;
    wire do_pop  = i_ce && pop  && !empty_r;
    wire [1:0] nw = wptr + do_push;
    wire [1:0] nr = rptr + do_pop;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 2'd0; rptr <= 2'd0; count <= 3'd0;
            empty_r <= 1'b1; full_r <= 1'b0;
        end else begin
            wptr <= nw;
            rptr <= nr;
            empty_r <= (nw == nr) && (do_pop  || (empty_r && !do_push));
            full_r  <= (nw == nr) && (do_push || (full_r  && !do_pop));
            count <= count + do_push - do_pop;
        end
    end

    always @(posedge clk)
        if (empty_r)
            assert (!full_r);
endmodule","top_module":"ringq","clock":"clk","antecedents":["empty_r"],"sanity_covers":["full_r","count == 3'd4"]}

{"cti_reasoning":"In state S the hit counter equals the total (so o_all_hits is high) but the miss counter is one larger than the total, so o_all_misses is low and P holds; S violates R because total(2) != hits(2)+misses(3). The design can sit in S indefinitely with i_ce low, and one enabled step with a matching character makes total=3, hits=3, misses=3, driving both o_all_hits and o_all_misses high and breaking P.","cti_state":[{"signal":"total","value":"4'd2"},{"signal":"hits","value":"4'd2"},{"signal":"misses","value":"4'd3"}],"invariants":["total == hits + misses"],"verilog":"module char_tally (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire [7:0] i_char,
    input wire [7:0] i_target,
    output wire o_all_hits,
    output wire o_all_misses
);
    reg [3:0] total, hits, misses;
    initial total  = 4'd0;
    initial hits   = 4'd0;
    initial misses = 4'd0;

    wire match = (i_char == i_target);

    always @(posedge clk)
        if (rst) begin
            total  <= 4'd0;
            hits   <= 4'd0;
            misses <= 4'd0;
        end else if (i_ce && (total != 4'hf)) begin
            total <= total + 4'd1;
            if (match) hits   <= hits   + 4'd1;
            else       misses <= misses + 4'd1;
        end

    assign o_all_hits   = (total != 4'd0) && (hits   == total);
    assign o_all_misses = (total != 4'd0) && (misses == total);

    always @(*)
        if (o_all_hits) assert (!o_all_misses);
endmodule","top_module":"char_tally","clock":"clk","antecedents":["o_all_hits"],"sanity_covers":["o_all_hits","total == 4'd3"]}

{"cti_reasoning":"The state sp=0 with the empty flag stuck low satisfies P (full is low and sp=0 <= 4) but violates R, which requires empty == (sp == 0); the design can sit in it forever with push=pop=0, and a single pop is then wrongly enabled, wrapping sp to 3'd7 while full stays low, so the next state has !full && sp > 4 and P fails.","cti_state":[{"signal":"sp","value":"3'd0"},{"signal":"empty","value":"1'b0"},{"signal":"full","value":"1'b0"}],"invariants":["empty == (sp == 3'd0)","full == (sp == 3'd4)"],"verilog":"module stack_ptr_guard (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    input wire [7:0] din,
    output wire [7:0] dout,
    output reg [2:0] sp,
    output reg empty,
    output reg full
);
    reg [7:0] mem [0:3];

    initial sp    = 3'd0;
    initial empty = 1'b1;
    initial full  = 1'b0;

    assign dout = empty ? 8'h00 : mem[sp - 3'd1];

    always @(posedge clk) begin
        if (rst) begin
            sp    <= 3'd0;
            empty <= 1'b1;
            full  <= 1'b0;
        end else if (push && !pop && !full) begin
            mem[sp] <= din;
            sp      <= sp + 3'd1;
            empty   <= 1'b0;
            full    <= (sp == 3'd3);
        end else if (pop && !push && !empty) begin
            sp    <= sp - 3'd1;
            full  <= 1'b0;
            empty <= (sp == 3'd1);
        end
    end

    always @(posedge clk)
        if (!full) assert (sp <= 3'd4);
endmodule","top_module":"stack_ptr_guard","clock":"clk","antecedents":["!full"],"sanity_covers":["sp == 3'd2","full == 1'b1"]}

{"cti_reasoning":"State count=3'd1, wptr=2'd0, rptr=2'd0 satisfies P because the guard count==0 is false, but it violates R since the pointer difference (wptr-rptr)&3 = 0 does not equal count[1:0] = 1. With i_push=i_pop=0 the FIFO idles in this state indefinitely; then a single pop (legal because count!=0) advances rptr to 2'd1 and drops count to 0, so P's guard fires with wptr=0 != rptr=1 and P fails.","cti_state":[{"signal":"count","value":"3'd1"},{"signal":"wptr","value":"2'd0"},{"signal":"rptr","value":"2'd0"}],"invariants":["count <= 3'd4","(count != 3'd4) || (wptr == rptr)","(count == 3'd4) || (((wptr - rptr) & 2'b11) == count[1:0])"],"verilog":"module qring (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty
);
    reg [1:0] wptr;
    reg [1:0] rptr;
    reg [2:0] count;

    initial wptr  = 2'd0;
    initial rptr  = 2'd0;
    initial count = 3'd0;

    assign o_full  = (count == 3'd4);
    assign o_empty = (count == 3'd0);

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  && !o_empty;

    always @(posedge clk)
        if (rst) begin
            wptr  <= 2'd0;
            rptr  <= 2'd0;
            count <= 3'd0;
        end else begin
            if (do_push) wptr <= wptr + 2'd1;
            if (do_pop)  rptr <= rptr + 2'd1;
            if (do_push && !do_pop) count <= count + 3'd1;
            else if (do_pop && !do_push) count <= count - 3'd1;
        end

    always @(*)
        if (count == 3'd0)
            assert (wptr == rptr);
endmodule","top_module":"qring","clock":"clk","antecedents":["count == 3'd0"],"sanity_covers":["count == 3'd2","count == 3'd4"]}

{"cti_reasoning":"In state S the staged character is still in flight (st_valid=1), so the guard !st_valid is false and P holds trivially; S violates R because the in-flight match is not yet accounted for (cnt + 1 = 6 > total = 5). The design idles in S while ce=0 and flush=0, and a single flush commits the staged match, giving cnt=6, total=5 with st_valid=0, so P fails.","cti_state":[{"signal":"cnt","value":"6'd5"},{"signal":"total","value":"6'd5"},{"signal":"st_valid","value":"1'b1"},{"signal":"st_match","value":"1'b1"}],"invariants":["(cnt + ((st_valid && st_match) ? 6'd1 : 6'd0)) <= total"],"verilog":"module strcount_pipe (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire flush,
    input wire [7:0] ch,
    output wire [5:0] o_cnt
);
    parameter [7:0] TARGET = 8'h61;

    reg [5:0] total = 6'd0;   // characters accepted
    reg [5:0] cnt   = 6'd0;   // committed occurrences of TARGET
    reg       st_valid = 1'b0; // staged character present
    reg       st_match = 1'b0; // staged character equals TARGET

    wire full   = (total == 6'd63);
    wire accept = ce && !full;

    always @(posedge clk)
        if (rst) begin
            total    <= 6'd0;
            cnt      <= 6'd0;
            st_valid <= 1'b0;
            st_match <= 1'b0;
        end else if (accept) begin
            total    <= total + 6'd1;
            st_valid <= 1'b1;
            st_match <= (ch == TARGET);
            if (st_valid && st_match)
                cnt <= cnt + 6'd1;
        end else if (flush && st_valid) begin
            st_valid <= 1'b0;
            if (st_match)
                cnt <= cnt + 6'd1;
        end

    assign o_cnt = cnt;

    always @(*)
        if (!st_valid)
            assert (cnt <= total);
endmodule","top_module":"strcount_pipe","clock":"clk","antecedents":["!st_valid"],"sanity_covers":["!st_valid && cnt == 6'd1","!st_valid && total == 6'd3"]}

{"cti_reasoning":"The state items=1, sp=2, top_valid=1 satisfies P vacuously (the guard items==0 is false) but violates R because the occupancy counter disagrees with the stack pointer; with push and pop both low the design sits here forever, and a single pop step yields items=0 while top_valid stays 1 (since sp was 2, not 1), breaking P.","cti_state":[{"signal":"items","value":"3'd1"},{"signal":"sp","value":"3'd2"},{"signal":"top_valid","value":"1'b1"}],"invariants":["items == sp","sp <= 3'd4","top_valid == (sp != 3'd0)"],"verilog":"module stack_occupancy (
    input wire clk,
    input wire rst,
    input wire push,
    input wire pop,
    output reg [2:0] sp,
    output reg [2:0] items,
    output reg top_valid
);
    initial sp = 3'd0;
    initial items = 3'd0;
    initial top_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 3'd0;
            items     <= 3'd0;
            top_valid <= 1'b0;
        end else if (push && sp != 3'd4) begin
            sp        <= sp + 3'd1;
            items     <= items + 3'd1;
            top_valid <= 1'b1;
        end else if (pop && sp != 3'd0) begin
            sp        <= sp - 3'd1;
            items     <= items - 3'd1;
            top_valid <= (sp != 3'd1);
        end
    end

    // P: an empty stack (per the occupancy counter) must not advertise a valid top
    always @(posedge clk)
        if (items == 3'd0)
            assert (top_valid == 1'b0);
endmodule","top_module":"stack_occupancy","clock":"clk","antecedents":["items == 3'd0"],"sanity_covers":["items == 3'd2","sp == 3'd4","top_valid == 1'b1"]}

{"cti_reasoning":"In the state phase=STOP with bit_cnt=3'd5 the property's guard (phase==IDLE) is false, so P holds; the invariant is violated because every legitimately reachable STOP state has bit_cnt==3'd0 (the DATA->STOP transition clears it). With ce=0 the design sits in this state forever, and one cycle with ce=1 moves phase to IDLE while leaving bit_cnt at 3'd5, so the next state has phase==IDLE and bit_cnt!=0 and P fails.","cti_state":[{"signal":"phase","value":"2'd3"},{"signal":"bit_cnt","value":"3'd5"},{"signal":"sh","value":"8'h00"},{"signal":"tx","value":"1'b1"}],"invariants":["(phase == 2'd2) || (bit_cnt == 3'd0)","bit_cnt <= 3'd7"],"verilog":"module uart_tx (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire [7:0] data,
    output reg tx
);
    localparam IDLE = 2'd0, ST = 2'd1, DAT = 2'd2, STP = 2'd3;
    reg [1:0] phase;
    reg [2:0] bit_cnt;
    reg [7:0] sh;
    initial begin phase = IDLE; bit_cnt = 3'd0; sh = 8'h00; tx = 1'b1; end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; bit_cnt <= 3'd0; sh <= 8'h00; tx <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (start) begin
                          phase <= ST; sh <= data; tx <= 1'b0; bit_cnt <= 3'd0;
                      end
                ST:   begin
                          phase <= DAT; tx <= sh[0]; sh <= {1'b0, sh[7:1]};
                          bit_cnt <= 3'd0;
                      end
                DAT:  if (bit_cnt == 3'd7) begin
                          phase <= STP; tx <= 1'b1; bit_cnt <= 3'd0;
                      end else begin
                          bit_cnt <= bit_cnt + 3'd1; tx <= sh[0];
                          sh <= {1'b0, sh[7:1]};
                      end
                STP:  begin phase <= IDLE; tx <= 1'b1; end
            endcase
        end
    end

    always @(posedge clk)
        if (phase == IDLE)
