    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
    output reg  [3:0] count
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

