            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
            deadline <= MAXSTEP;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
