{"cti_reasoning": "In state S the arming register is set and the shift register holds a single in-flight token at stage 2 (pipe=4'b0100) while the occupancy counter reads 0, so the relation occ == popcount(pipe) is violated, yet the property holds because the guard needs pipe[3] (the drain stage) to be set and it is not. With i_ce low the design freezes in S for arbitrarily many cycles; one step with i_ce=1 and i_issue=0 shifts the token into the drain stage (pipe=4'b1000) while occ stays 0 and armed stays 1, and the next evaluation of the guarded check asserts occ != 0 on a retirement with zero recorded occupancy, which fails.", "cti_state": [{"signal": "pipe", "value": "4'b0100"}, {"signal": "occ", "value": "3'd0"}, {"signal": "armed", "value": "1'b1"}, {"signal": "sh_occ", "value": "3'd1"}], "invariants": ["occ == (pipe[0] + pipe[1] + pipe[2] + pipe[3])", "!armed || sh_occ != 3'd0"], "verilog": "module serv_inflight_tracker (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,      // idle condition: all state frozen when low
    input  wire       i_issue,   // issue a new operation into the pipeline
    output wire       o_retire,
    output wire [2:0] o_occ
);
    localparam LAT = 4;

    // fixed-latency drain shift register: one bit per pipeline stage
    reg [LAT-1:0] pipe;
    initial pipe = {LAT{1'b0}};

    // in-flight occupancy counter: issue increments, drain decrements
    reg [2:0] occ;
    initial occ = 3'd0;

    // window register (scope): armed by an issue, cleared by a retirement
    reg armed;
    initial armed = 1'b0;

    // shadow register: occupancy recorded at the arming issue
    reg [2:0] sh_occ;
    initial sh_occ = 3'd0;

    wire       drain   = pipe[LAT-1];
    wire [2:0] occ_nxt = occ + {2'b00, i_issue} - {2'b00, drain};

    always @(posedge i_clk) begin
        if (i_reset) begin
            pipe   <= {LAT{1'b0}};
            occ    <= 3'd0;
            armed  <= 1'b0;
            sh_occ <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[LAT-2:0], i_issue};
            occ  <= occ_nxt;
            if (i_issue) begin
                armed  <= 1'b1;
                sh_occ <= occ_nxt;
            end else if (drain) begin
                armed <= 1'b0;
            end
        end
    end

    assign o_retire = i_ce & drain;
    assign o_occ    = occ;

    // Precedence, after issue until retire: a retirement observed inside the
    // armed window must have been preceded by a recorded, still-accounted issue.
    always @(posedge i_clk)
        if (armed && i_ce && drain)
            assert (occ != 3'd0 && sh_occ != 3'd0);
endmodule", "top_module": "serv_inflight_tracker", "clock": "i_clk", "antecedents": ["armed", "i_ce", "pipe[3]"], "sanity_covers": ["armed == 1'b1", "armed && pipe[3]", "occ == 3'd2"]}

{"cti_reasoning": "S has the FSM in the one-hot IDLE state but with the frame phase counter already loaded with 1 (nbits==4'd1), which satisfies P (while rx is held high nothing moves, so both nbits and st are stable and nbits<=10) yet violates the invariant clause that ties st[0] to nbits==4'd0. The design can idle in S indefinitely (rx=1, or ce=0), and one step with ce=1 and rx=0 takes the start-bit detection path: st changes from IDLE to START while the counter is *loaded* with the constant 4'd1 and therefore does not change, so $stable(nbits) holds while $stable(st) fails and P breaks.", "cti_state": [{"signal": "st", "value": "11'b000_0000_0001"}, {"signal": "nbits", "value": "4'd1"}, {"signal": "pv", "value": "1'b1"}, {"signal": "sr", "value": "8'h00"}, {"signal": "ferr", "value": "1'b0"}], "invariants": ["st != 11'd0", "(st & (st - 11'd1)) == 11'd0", "nbits <= 4'd10", "!st[0] || nbits == 4'd0", "!st[1] || nbits == 4'd1", "!st[2] || nbits == 4'd2", "!st[3] || nbits == 4'd3", "!st[4] || nbits == 4'd4", "!st[5] || nbits == 4'd5", "!st[6] || nbits == 4'd6", "!st[7] || nbits == 4'd7", "!st[8] || nbits == 4'd8", "!st[9] || nbits == 4'd9", "!st[10] || nbits == 4'd10"], "verilog": "module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
            if (done)          ferr  <= !rx;    // stop bit must be high
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);
endmodule", "top_module": "uart_rx_onehot", "clock": "clk", "antecedents": ["pv", "$stable(nbits)"], "sanity_covers": ["nbits == 4'd5", "nbits == 4'd10", "st[10] == 1'b1"]}

{"cti_reasoning": "State S has bin=4'd9 but gray=4'b0000, so the popcount `ones` is 0 and occ_hi is low — no rising edge, so P holds, and it holds for arbitrarily many cycles while i_ce is low. S violates R because gray != (bin ^ (bin>>1)) = 4'b1101, hence the terminal-count detect (gray == 4'b1101) misses: one enabled step sets bin to 4'd10 and gray to 4'b1111, so `ones` jumps to 4 and occ_hi rises with ones == 4, breaking P.", "cti_state": [{"signal": "bin", "value": "4'd9"}, {"signal": "gray", "value": "4'b0000"}, {"signal": "pv", "value": "1'b1"}, {"signal": "i_ce", "value": "1'b0"}], "invariants": ["gray == (bin ^ (bin >> 1))", "bin <= 4'd9"], "verilog": "module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

    wire       wrap    = (gray == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin_nxt;
            gray <= bin_nxt ^ (bin_nxt >> 1);
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule", "top_module": "gray_quantum_counter", "clock": "clk", "antecedents": ["$rose(occ_hi)"], "sanity_covers": ["ones == 3'd3", "bin == 4'd9"]}

{"cti_reasoning": "The state lfsr=0 (the LFSR all-zeros lockup) with credit=used=0 satisfies both assertions, since gnt_a, gnt_b, f_full and f_empty are all low, but it violates R (lfsr must be nonzero and credit+used must equal 4). With ce low the design sits in that state forever; one step with ce high drives gnt_a and gnt_b both high (the lock path) and, because both credit and used are zero, also latches f_full and f_empty high, so both assertions fail in the next state.", "cti_state": [{"signal": "lfsr", "value": "4'b0000"}, {"signal": "credit", "value": "3'd0"}, {"signal": "used", "value": "3'd0"}, {"signal": "gnt_a", "value": "1'b0"}, {"signal": "gnt_b", "value": "1'b0"}, {"signal": "f_full", "value": "1'b0"}, {"signal": "f_empty", "value": "1'b0"}, {"signal": "armed", "value": "1'b1"}], "invariants": ["lfsr != 4'd0", "credit <= 3'd4", "used <= 3'd4", "credit + used == 3'd4"], "verilog": "module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
    output wire o_empty
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
    wire       lock = (lfsr == 4'd0);

    // token movement between the two credit pools, steered by the LFSR
    wire take_a = lfsr[0]  && (credit != 3'd0);
    wire give_b = !lfsr[0] && (used   != 3'd0);

    wire [2:0] nc = take_a ? (credit - 3'd1) : (give_b ? (credit + 3'd1) : credit);
    wire [2:0] nu = take_a ? (used   + 3'd1) : (give_b ? (used   - 3'd1) : used);

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= nxt;

            // grant decode: in the lockup state the decode degenerates and
            // asserts both grants at once
            gnt_a <= lock ? 1'b1 : nxt[0];
            gnt_b <= lock ? 1'b1 : !nxt[0];

            credit <= nc;
            used   <= nu;

            f_full  <= (nc == 3'd0);
            f_empty <= (nu == 3'd0);

            if (lfsr == 4'hF)
                armed <= 1'b1;
        end
    end

    assign o_gnt_a = gnt_a;
    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule", "top_module": "lfsr_token_arbiter", "clock": "clk", "antecedents": ["armed"], "sanity_covers": ["armed", "armed && credit == 3'd2"]}

{"cti_reasoning": "In state S the occupancy register nact already holds 4 so the guarded property (heating implies nact <= 4) is satisfied, and the stored parity matches the stored zone mask so no fault is flagged; S violates R because nact does not equal the population count of zone (1) and because budget+nact is 7 instead of 4. With i_ce low the design sits in S forever, and one cycle with i_ce high, i_temp below T_LOW and i_zone=1 turns on an idle zone (budget is non-zero so the grant fires), pushing nact to 5 while zone stays non-zero, so the property fails.", "cti_state": [{"signal": "zone", "value": "8'h01"}, {"signal": "zpar", "value": "1'b1"}, {"signal": "nact", "value": "4'd4"}, {"signal": "budget", "value": "4'd3"}], "invariants": ["zpar == (^zone)", "nact == ({3'b000,zone[0]} + {3'b000,zone[1]} + {3'b000,zone[2]} + {3'b000,zone[3]} + {3'b000,zone[4]} + {3'b000,zone[5]} + {3'b000,zone[6]} + {3'b000,zone[7]})", "({1'b0,budget} + {1'b0,nact}) == 5'd4"], "verilog": "// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule", "top_module": "zone_heat_budget", "clock": "i_clk", "antecedents": ["heating"], "sanity_covers": ["heating && nact == 4'd4", "heating && nact == 4'd2", "budget == 4'd0"]}

{"cti_reasoning": "The state S has pipe=4'b1000 (one request about to retire) but count=3'd0 and started=0, so it satisfies P vacuously (fin is low, so the guard is false) while violating R (count must equal the popcount of pipe, and a non-zero pipe must imply started). With i_ce low the design sits in S forever; one step with i_ce=1 registers fin<=pipe[3]=1, and at that next cycle armed&&fin holds while $past(count)==0 and started==0, so P fails.", "cti_state": [{"signal": "armed", "value": "1'b1"}, {"signal": "started", "value": "1'b0"}, {"signal": "pipe", "value": "4'b1000"}, {"signal": "count", "value": "3'd0"}, {"signal": "fin", "value": "1'b0"}, {"signal": "pv", "value": "1'b1"}], "invariants": ["count == ({2'd0,pipe[0]} + {2'd0,pipe[1]} + {2'd0,pipe[2]} + {2'd0,pipe[3]})", "(pipe == 4'b0000) || started", "!started || armed"], "verilog": "// Tracks in-flight fabrication requests through a 4-stage shift register,
// with a separately maintained population count of the outstanding requests.
// Chain: the board must be armed, then a request may start, then it may finish.
module inflight_chain (
    input  wire clk,
    input  wire rst,
    input  wire i_arm,      // Q event: arms the pipeline (sticky)
    input  wire i_ce,       // enable; when low, all pipeline state holds
    input  wire i_start,    // request injection
    output wire o_busy,
    output wire o_fin
);
    reg       armed   = 1'b0;   // sticky scope register
    reg       started = 1'b0;   // sticky: a request was ever injected
    reg [3:0] pipe    = 4'b0000;
    reg [2:0] count   = 3'd0;   // set-bit count of pipe, kept incrementally
    reg       fin     = 1'b0;   // registered finish pulse
    reg       pv      = 1'b0;   // past-valid

    wire inject = armed && i_start;
    wire retire = pipe[3];

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            pipe    <= 4'b0000;
            count   <= 3'd0;
            fin     <= 1'b0;
        end else begin
            if (i_arm)
                armed <= 1'b1;
            if (i_ce) begin
                pipe  <= {pipe[2:0], inject};
                count <= count + (inject ? 3'd1 : 3'd0) - (retire ? 3'd1 : 3'd0);
                fin   <= retire;
                if (inject)
                    started <= 1'b1;
            end
        end
    end

    assign o_busy = (count != 3'd0);
    assign o_fin  = fin;

    // Chain precedence, after the pipeline has been armed: a finish can only be
    // observed if a request had actually started and was in flight last cycle.
    always @(posedge clk)
        if (pv && armed && fin)
            assert (started && ($past(count) != 3'd0));
endmodule", "top_module": "inflight_chain", "clock": "clk", "antecedents": ["armed", "fin"], "sanity_covers": ["armed && fin", "count == 3'd2", "armed && started && pipe == 4'b0010"]}

{"cti_reasoning": "The state phase=1 (req asserted, ack not yet seen) with idle_r still 1 satisfies P because busy_r is 0, but it violates R, whose clause idle_r == (phase == 2'd0) forces idle_r low outside the idle phase; the design can sit here forever with i_ce low, and one step with slave_ack asserted moves phase 1->2 which sets busy_r to 1 while idle_r remains 1, so P (never both idle and busy) fails in the next state.", "cti_state": [{"signal": "phase", "value": "2'd1"}, {"signal": "req_r", "value": "1'b1"}, {"signal": "ack_r", "value": "1'b0"}, {"signal": "idle_r", "value": "1'b1"}, {"signal": "busy_r", "value": "1'b0"}], "invariants": ["req_r == (phase == 2'd1 || phase == 2'd2)", "ack_r == (phase == 2'd2 || phase == 2'd3)", "idle_r == (phase == 2'd0)", "busy_r == (phase == 2'd2 || phase == 2'd3)"], "verilog": "// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
                    if (start) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                        busy_r <= 1'b0;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
endmodule", "top_module": "fourphase_handshake", "clock": "clk", "antecedents": [], "sanity_covers": ["phase == 2'd2", "phase == 2'd3"]}

